#include "sim/MissionTriggerDestruction.hpp"
#include <array>
#include <iostream>
#include <sstream>
using namespace ra2;
namespace {
void require(bool ok){if(!ok)throw std::invalid_argument("Mission Trigger destruction fixture outside domain");}
struct Input {char op='P';int typeMode=1,firstPresent=1,destroyed=0;std::uint32_t deleting=1,removed=1;std::int32_t qcount=0;std::array<int,8> q{};std::array<std::int32_t,4> rcount{};std::array<std::array<int,6>,4> r{};};
Input parse(std::istream& in){Input f;require(bool(in>>f.op>>f.typeMode>>f.firstPresent>>f.destroyed>>f.deleting>>f.removed>>f.qcount));require(f.op=='P'||f.op=='D'||f.op=='C');require(f.typeMode>=0&&f.typeMode<=2&&f.firstPresent>=0&&f.firstPresent<=1&&f.destroyed>=0&&f.destroyed<=255&&f.qcount>=0&&f.qcount<=8);for(auto& x:f.q){require(bool(in>>x));require(x>=0&&x<=2);}for(int j=0;j<4;++j){require(bool(in>>f.rcount[j]));require(f.rcount[j]>=0&&f.rcount[j]<=6);for(auto& x:f.r[j]){require(bool(in>>x));require(x>=0&&x<=2);}}if(f.op=='C')require(f.typeMode==1&&f.firstPresent==1&&f.qcount>0);std::string extra;require(!(in>>extra));return f;}
void run(std::istream& in){auto f=parse(in);std::int32_t persistence=0,instances=0;std::uint8_t executing=0,tagDestroyed=std::uint8_t(f.destroyed);MissionTagType type{persistence};MissionTagType* typePointer=&type;
    std::int32_t frame=0,padding=0,countryIndex=0;std::uint8_t triggerDestroyed=1,enabled=0,suppress=0;std::uint32_t occurred=0;MissionTriggerCountry country{countryIndex};MissionTriggerEvent* event=nullptr;MissionTriggerAction* action=nullptr;MissionTriggerType triggerType{&country,event,action};auto* triggerTypePointer=&triggerType;MissionEventTimer timer{};MissionTriggerState triggerState{triggerTypePointer,triggerDestroyed,enabled,timer,padding,occurred};MissionTriggerServices triggerServices{frame,suppress};MissionTagTrigger* next=nullptr;MissionTagTrigger trigger{triggerState,triggerServices,next};if(f.typeMode==0)typePointer=nullptr;else if(f.typeMode==2)typePointer=reinterpret_cast<MissionTagType*>(&trigger);MissionTagTrigger* first=f.firstPresent?&trigger:nullptr;MissionTagState tag{typePointer,first,instances,executing};
    std::int32_t capacity=12,growth=1;std::uint8_t owns=1;std::array<const void*,12> qback{};std::span<const void*> qslots=qback;MissionDeferredDelete queue{capacity,owns,f.qcount,growth,qslots,{}};auto pointer=[&](int id)->const void*{return id==1?static_cast<const void*>(&trigger):id==2?static_cast<const void*>(&tag):nullptr;};for(std::size_t i=0;i<f.q.size();++i)qback[i]=pointer(f.q[i]);
    std::array<std::array<const void*,8>,4> rback{};std::array<std::span<const void*>,4> rslots{rback[0],rback[1],rback[2],rback[3]};int ridentity[4]{};std::array<MissionExpirationVector<const void*>,4> registries{{{f.rcount[0],rslots[0],&ridentity[0]},{f.rcount[1],rslots[1],&ridentity[1]},{f.rcount[2],rslots[2],&ridentity[2]},{f.rcount[3],rslots[3],&ridentity[3]}}};for(int j=0;j<4;++j)for(int i=0;i<6;++i)rback[j][i]=pointer(f.r[j][i]);
    auto id=[&](const void* p){if(!p)return 0;if(p==&trigger)return 1;if(p==&tag)return 2;if(p==&queue)return 40;for(int j=0;j<4;++j)if(p==&ridentity[j])return 50+j;throw std::invalid_argument("Unknown Trigger destruction identity");};MissionTagStore store=[&](const void* p,auto off,auto value,const void* pv){std::cout<<"W "<<id(p)<<' '<<off<<' '<<(pv?id(pv):int(value))<<' ';};
    MissionTagPointerReferences owner{tag,typePointer,first,tagDestroyed,&tag};MissionExpiredTriggerReference expired{&trigger,next};int triggerBase=0,triggerFree=0,tagBase=0,tagFree=0;
    MissionTriggerDestructionServices triggerDestruction{{&registries[0],&registries[1],&registries[2]}};triggerDestruction.store=store;triggerDestruction.expire=[&](auto& subject,auto removed){require(&subject==&trigger);std::cout<<"N 1 ";expireMissionTagPointerReferences(owner,expired,removed,queue,store);};triggerDestruction.destroyBase=[&](auto&){++triggerBase;std::cout<<"B 1 ";};triggerDestruction.freeRecord=[&](auto&){++triggerFree;std::cout<<"F 1 ";};
    std::uint8_t session=0;MissionTagDestructionServices tagDestruction{queue,{&registries[1],&registries[2],&registries[3]},{},{},{},store,session};tagDestruction.expire=[&](auto&,auto){std::cout<<"N 2 ";};tagDestruction.destroyBase=[&](auto&){++tagBase;std::cout<<"B 2 ";};tagDestruction.freeRecord=[&](auto&){++tagFree;std::cout<<"F 2 ";};
    if(f.op=='P')expireMissionTagPointerReferences(owner,expired,f.removed,queue,store);
    else if(f.op=='D')destroyMissionTriggerRecord(trigger,f.deleting,triggerDestruction);
    else {auto triggerRecord=bindMissionTriggerDestruction(trigger,triggerDestruction);auto tagRecord=bindMissionTagDestruction(tag,tagDestruction);MissionDeferredCleanupServices cleanup{queue};cleanup.store=store;cleanup.resolve=[&](const void* p)->MissionDeferredCleanupRecord&{if(p==&trigger)return triggerRecord;if(p==&tag)return tagRecord;throw std::invalid_argument("Unknown Trigger lifetime record");};drainMissionDeferredCleanup(cleanup);}
    std::cout<<"state "<<f.typeMode<<' '<<int(typePointer!=nullptr)<<' '<<int(first!=nullptr)<<' '<<int(tagDestroyed)<<' '<<f.qcount;for(auto* p:qback)std::cout<<' '<<id(p);for(int j=0;j<4;++j){std::cout<<' '<<f.rcount[j];for(auto* p:rback[j])std::cout<<' '<<id(p);}std::cout<<' '<<triggerBase<<' '<<triggerFree<<' '<<tagBase<<' '<<tagFree<<'\n';
}
void guards(){std::int32_t persistence=0,instances=0,capacity=1,count=0,growth=1;std::uint8_t executing=0,destroyed=0,owns=1;MissionTagType type{persistence};auto* typePointer=&type;MissionTagTrigger* first=nullptr;MissionTagState tag{typePointer,first,instances,executing};std::array<const void*,2> backing{};std::span<const void*> slots=backing;MissionDeferredDelete queue{capacity,owns,count,growth,slots,{}};MissionTagPointerReferences owner{tag,typePointer,first,destroyed,&tag};MissionTagTrigger* next=nullptr;int identity=0;MissionExpiredTriggerReference expired{&identity,next};expireMissionTagPointerReferences(owner,expired,0,queue);require(typePointer==&type&&!first&&!destroyed&&!count);typePointer=nullptr;expireMissionTagPointerReferences(owner,expired,0,queue);require(destroyed==1&&count==1&&backing[0]==&tag);std::cout<<"mission trigger destruction guards PASS\n";}
}
int main(int argc,char** argv){try{if(argc==2&&std::string(argv[1])=="--guards"){guards();return 0;}require(argc==1);std::string line;while(std::getline(std::cin,line)){std::istringstream in(line);run(in);}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
